<?php require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/config/db.php';if(empty($_SESSION['user_id'])){header('Location: auth/login.php');exit;}$message='';if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf_token']??null)){try{$q=db()->prepare('UPDATE users SET full_name=?,phone=? WHERE id=?');$q->execute([trim($_POST['full_name']),trim($_POST['phone']),$_SESSION['user_id']]);$_SESSION['user_name']=trim($_POST['full_name']);$message='Profile updated.';}catch(Throwable $e){$message='Unable to update profile.';}}$pageTitle='Settings';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';?><main class="container py-5" style="max-width:650px"><h1 class="h2">Settings</h1><?php if($message):?><div class="alert alert-info"><?=e($message)?></div><?php endif;?><form method="post" class="profile-section"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-label">Full name</label><input class="form-control mb-3" name="full_name" value="<?=e($_SESSION['user_name']??'')?>" required><label class="form-label">Phone</label><input class="form-control mb-3" name="phone"><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" id="darkMode"><label class="form-check-label" for="darkMode">Dark mode</label></div><button class="btn btn-brand">Save changes</button></form></main><script>const d=document.querySelector('#darkMode');d.checked=localStorage.theme==='dark';d.onchange=()=>{localStorage.theme=d.checked?'dark':'light';document.body.classList.toggle('dark-mode',d.checked)}</script><?php require __DIR__.'/includes/footer.php';?>
